import numpy as np, sys
L=open(sys.argv[1]).read().split('\n'); n=int(L[0]); at=[l.split() for l in L[2:2+n]]
sym=[a[0] for a in at]; X=np.array([[float(v) for v in a[1:4]] for a in at])
def d(i,j): return np.linalg.norm(X[i]-X[j])
def ang(i,j,k):
    a=X[i]-X[j]; b=X[k]-X[j]; return np.degrees(np.arccos(np.dot(a,b)/np.linalg.norm(a)/np.linalg.norm(b)))
co=7
for i in [6,8,20,39,57]: print(sym[i],i,round(d(co,i),3))
for p in [(6,7,57),(20,7,39),(20,7,8),(39,7,8),(6,7,8),(6,7,20),(6,7,39)]: print(p, round(ang(*p),1))
# bond connectivity check
from itertools import combinations
cnt=0
for i in range(n):
    for j in range(i+1,n):
        if sym[i]!='Co' and sym[j]!='Co' and d(i,j)<0.9: print("CLASH",i,j,d(i,j))
